// Scorecard data for the introduction, derived from data/intro.json
// (generated by scripts/intro-data.mjs from experiments/intro-scorecard/results).
import intro from './intro.json'

export type Grade = 'win' | 'ok' | 'lose' | 'na'

export interface Cell {
  value: string
  note?: string
  grade: Grade
}

export interface Column {
  id: string
  label: string
  sub?: string
  highlight?: boolean
}

export interface Row {
  label: string
  detail?: string
  cells: Record<string, Cell>
}

export { intro }

export const languages: Column[] = [
  { id: 'go', label: 'Go' },
  { id: 'python', label: 'Python' },
  { id: 'node', label: 'Node' },
  { id: 'java', label: 'Java', sub: 'JDK 25', highlight: true },
]

export const provisional = intro.runs.measured < intro.planned
export const status = provisional
  ? `Provisional: ${intro.runs.measured} of ${intro.planned} runs`
  : `${intro.runs.measured} runs`

const ms = (v: number) => (v < 10 ? `${v.toFixed(1)} ms` : `${Math.round(v)} ms`)
const ratio = (v: number) => `${v.toFixed(2)}x`
const bytes = (v: number) => (v >= 1e6 ? `${(v / 1e6).toFixed(1)} MB` : `${Math.max(1, Math.round(v / 1e3))} KB`)
const tokens = (v: number) => (v >= 1000 ? `${(v / 1000).toFixed(1)}k` : `${Math.round(v)}`)

type Lang = keyof typeof intro.compare

/**
 * Lower is better. Best value (within 10%) wins; within 1.25x of the row median is ok; anything else loses.
 */
function row(label: string, detail: string, pick: (l: Lang) => number | null, format: (v: number) => string,
  notes: Partial<Record<Lang, string>> = {}, missing = 'n/a'): Row {
  const ids = languages.map(c => c.id as Lang)
  const values = ids.map(pick).filter((v): v is number => v != null)
  const sorted = [...values].sort((a, b) => a - b)
  const best = sorted[0]
  const mid = sorted.length % 2 ? sorted[(sorted.length - 1) / 2] : (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
  const cells: Record<string, Cell> = {}
  for (const id of ids) {
    const v = pick(id)
    cells[id] = v == null
      ? { value: missing, grade: 'na' }
      : { value: format(v), note: notes[id], grade: v <= best * 1.1 ? 'win' : v <= mid * 1.25 ? 'ok' : 'lose' }
  }
  return { label, detail, cells }
}

const c = intro.compare
const aot = c.java.aotStartupMs

const pct = (v: number) => `${Math.round(v * 100)}%`

export const introRows: Row[] = [
  row('Startup', 'as generated, median', l => c[l].startupMs, ms, { go: 'compiled binary' }),
  row('Startup, optimized', 'Java: jar + AOT cache', l => c[l].bestStartupMs, ms, { python: 'as is', node: 'as is', go: 'as is' }),
  row('Source size', 'tokens vs. Python', l => c[l].tokensVsPython, ratio),
  row('Disk', 'source + build + deps', l => c[l].diskBytes, bytes, { go: 'binary' }),
  row('Build step', 'share of programs', l => c[l].buildStepShare, pct),
  row('Launcher script', 'share of programs', l => c[l].launcherShare, pct),
]

// Hypothesis verdicts. Hypothesis 4 is judged against the bake-off baselines.
export interface Verdict {
  id: string
  hypothesis: number
  label: string
  expected: string
  verdict: string
  n: number
  count: number | null
  share: number | null
  ciLow: number | null
  ciHigh: number | null
  exceptions: number | null
  threshold: number | null
  comparison: string
  mostCommon: string | null
}

const labels: Record<string, [string, string]> = {
  'H1.python': ['Python', 'at least 50%'],
  'H1.scripting': ['A scripting language', 'at least 67%'],
  'H1.compiled': ['Another compiled language', 'at most 25%'],
  'H1.java': ['Java', 'less than 10%'],
  'H2.java': ['When asked, writes Java', '100%'],
  'H2.pass': ['Passes the tests', 'at least 85%'],
  'H3.distinct': ['Distinct Java program styles', 'at least 4'],
  'H3.max_share': ['Programs using the most common style', 'at most 67%'],
  'H4.startup.bake-off': ['Unoptimized programs start slower', 'every program'],
  'H4.source.bake-off': ['Java source is 25% larger', 'most programs'],
  'H4.disk.bake-off': ['With dependencies, more disk', 'every program'],
  'H4.optimization.bake-off': ['Optimized is within 2x of Python, Node', 'most programs'],
}

export const verdicts: Verdict[] = intro.verdicts
  .filter(v => labels[v.id])
  .map(v => ({ ...v, label: labels[v.id][0], expected: labels[v.id][1] }) as Verdict)

// The intro scorecard after javaw: same rows and values, except javaw takes over the build step and the
// launcher script for Java. The scorecard slide in Today swaps introRows for javawRows on a click.
export const javawColumns: Column[] = languages.map(col => col.id === 'java' ? { ...col, sub: 'JDK 25 + javaw' } : col)

const byJavaw: Record<string, Cell> = {
  'Build step': { value: pct(0), note: 'first run, by javaw', grade: 'win' },
  'Launcher script': { value: pct(0), note: 'generated by javaw', grade: 'win' },
}

// Startup, optimized: Java switches from jar + AOT cache to a native image of the same programs
// (experiments/intro-scorecard/harness/native.py, the native-image step a javaw --native wrapper runs). Regraded.
const jc = c.java as typeof c.java & { nativeStartupMs?: number | null, nativeDiskBytes?: number | null, nativePrograms?: number, aotPrograms?: number }
const nativeNote = jc.nativePrograms && jc.aotPrograms && jc.nativePrograms < jc.aotPrograms
  ? `${jc.nativePrograms} of ${jc.aotPrograms} programs`
  : undefined
const optimizedNative = row('Startup, optimized', 'Java: native', l => l === 'java' ? jc.nativeStartupMs ?? null : c[l].bestStartupMs, ms,
  { python: 'as is', node: 'as is', go: 'as is', java: nativeNote }, 'TBD')

// Disk: the native image is now part of what's on disk, like Go's binary.
const diskNative = row('Disk', 'source + build + deps', l => l === 'java' ? jc.nativeDiskBytes ?? null : c[l].diskBytes, bytes,
  { go: 'binary', java: 'native image' }, 'TBD')

export const javawRows: Row[] = introRows.map(r =>
  r.label === 'Startup, optimized' ? optimizedNative
  : r.label === 'Disk' ? diskNative
  : byJavaw[r.label] ? { ...r, cells: { ...r.cells, java: byJavaw[r.label] } }
  : r)
